import numpy as np

def transform_grid(grid):
    """Apply transformation rules based on my analysis"""
    result = grid.copy()
    height, width = grid.shape

    # Find all colored regions
    visited = np.zeros_like(grid, dtype=bool)
    regions = {}

    for i in range(height):
        for j in range(width):
            if grid[i,j] > 0 and not visited[i,j]:
                color = grid[i,j]
                region = []
                stack = [(i,j)]
                visited[i,j] = True

                while stack:
                    ci, cj = stack.pop()
                    region.append((ci,cj))
                    for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni, nj = ci+di, cj+dj
                        if 0 <= ni < height and 0 <= nj < width:
                            if grid[ni,nj] == color and not visited[ni,nj]:
                                visited[ni,nj] = True
                                stack.append((ni,nj))

                bounds = get_bounds(region)
                regions[color] = {'region': region, 'bounds': bounds}

    print(f"\nFound {len(regions)} regions:")
    for c, info in sorted(regions.items()):
        b = info['bounds']
        print(f"  Color {c}: rows {b['r_min']}-{b['r_max']}, cols {b['c_min']}-{b['c_max']}, count={len(info['region'])}")

    # Check adjacencies
    names = sorted(regions.keys())
    touching_pairs = set()
    for i, n1 in enumerate(names):
        for n2 in names[i+1:]:
            r1 = regions[n1]['bounds']
            r2 = regions[n2]['bounds']
            row_overlap = max(r1['r_min'], r2['r_min']) <= min(r1['r_max'], r2['r_max'])
            col_overlap = max(r1['c_min'], r2['c_min']) <= min(r1['c_max'], r2['c_max'])
            if row_overlap and col_overlap:
                touching_pairs.add((min(n1,n2), max(n1,n2)))
                print(f"\nTouching: {n1}-{n2}")

    return result, regions

