import numpy as np

def find_frames(grid):
    """Find individual rectangular frames of each color"""
    height, width = grid.shape
    frames = []

    # Scan for top-left corner of potential frames
    for i in range(height):
        for j in range(width):
            color = grid[i,j]
            if color > 0:
                # Check if this could be top-left of a frame
                # Frame starts here if we see horizontal line extending right
                frame_top = i
                frame_left = j

                # Find extent of this frame
                min_r, max_r = i, i
                min_c, max_c = j, j

                # Expand vertically and horizontally based on the border pattern
                visited_this_frame = {(i,j)}

                # BFS to find all cells belonging to this contiguous shape
                queue = [(i,j)]
                while queue:
                    r, c = queue.pop(0)

                    # Expand right along top edge
                    if r == frame_top and c+1 < width:
                        if grid[r, c+1] == color:
                            visited_this_frame.add((r, c+1))
                            queue.append((r, c+1))

                # Get bounds from this frame component
                coords = np.array(list(visited_this_frame))
                b = {
                    'r_min': coords[:,0].min(),
                    'r_max': coords[:,0].max(),
                    'c_min': coords[:,1].min(),
                    'c_max': coords[:,1].max()
                }
                frames.append({'color': color, 'bounds': b, 'coords': list(visited_this_frame)})

    return frames

# Simpler approach: detect rectangles by scanning for borders
def scan_rectangular_frames(grid):
    """Detect all rectangular frames in the grid"""
    height, width = grid.shape

    # For each cell that could be a frame corner
    frames = []

    for r in range(height):
        for c in range(width):
            if grid[r,c] > 0:
                color = grid[r,c]

                # Skip if already captured
                captured = False
                for f in frames:
                    if (r,c) in f['coords']:
                        captured = True
                        break

                if not captured:
                    # Trace out this contiguous region
                    region = set()
                    stack = [(r,c)]

                    while stack:
                        curr_r, curr_c = stack.pop()
                        if (curr_r, curr_c) in region:
                            continue

                        region.add((curr_r, curr_c))

                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < height and 0 <= nc < width:
                                if grid[nr,nc] == color and (nr,nc) not in region:
                                    stack.append((nr,nc))

                    # Calculate bounds
                    coords = np.array(list(region))
                    b = {
                        'r_min': int(coords[:,0].min()),
                        'r_max': int(coords[:,0].max()), 
                        'r_h': int(coords[:,0].max()) - int(coords[:,0].min()) + 1,
                        'c_min': int(coords[:,1].min()),
                        'c_max': int(coords[:,1].max()),
                        'c_w': int(coords[:,1].max()) - int(coords[:,1].min()) + 1,
                        'area': len(region)
                    }
                    frames.append({
                        'color': color,
                        'bounds': b,
                        'coords': list(region)
                    })

    return frames

