import numpy as np

# Now let's build a transformation function based on my best understanding
def transform_demo(grid):
    """Apply transformation rules"""
    result = grid.copy()

    # Find proper rectangular frames
    def is_proper_frame(g, r_min, r_max, c_min, c_max, color):
        for r in range(r_min, r_max + 1):
            for c in range(c_min, c_max + 1):
                if (r == r_min or r == r_max or c == c_min or c == c_max):
                    if g[r,c] != color:
                        return False
        return True

    # Find all proper frames
    def find_proper_frames(g):
        frames = []
        h, w = g.shape
        for r in range(h):
            for c in range(w):
                if g[r,c] > 0:
                    color = g[r,c]
                    # Expand to find bounding box of connected component
                    region = set()
                    stack = [(r,c)]

                    while stack:
                        cr, cc = stack.pop()
                        if (cr, cc) in region:
                            continue
                        region.add((cr, cc))

                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                            nr, nc = cr+dr, cc+dc
                            if 0 <= nr < h and 0 <= nc < w:
                                if g[nr,nc] == color and (nr,nc) not in region:
                                    stack.append((nr,nc))

                    coords = np.array(list(region))
                    b = {
                        'r_min': int(coords[:,0].min()),
                        'r_max': int(coords[:,0].max()),
                        'c_min': int(coords[:,1].min()),
                        'c_max': int(coords[:,1].max())
                    }

                    if is_proper_frame(g, b['r_min'], b['r_max'], b['c_min'], b['c_max'], color):
                        frames.append({
                            'color': color,
                            'bounds': b,
                            'coords': list(region)
                        })
        return frames

    frames = find_proper_frames(result)
    print(f"\nFound {len(frames)} proper frames")

    # Check nesting (one frame inside another of same color)
    def is_nested_inside(frame1, frame2):
        return (frame1['bounds']['r_min'] >= frame2['bounds']['r_min'] and
                frame1['bounds']['r_max'] <= frame2['bounds']['r_max'] and
                frame1['bounds']['c_min'] >= frame2['bounds']['c_min'] and
                frame1['bounds']['c_max'] <= frame2['bounds']['c_max'])

    # Apply transformations
    for f in frames:
        bounds = f['bounds']
        color = f['color']

        # Find all nested frames of same color
        nested_same_color = [fr for fr in frames if fr['color'] == color and is_nested_inside(fr, f)]

        if nested_same_color:
            # Keep original frame unchanged
            pass
        else:
            # Isolated - determine if remove or modify
            # For now, apply the color threshold rule:
            # Colors <= 5 (prime 5) → remove
            # Colors > 5 (composite 6, 8, etc.) → keep border

            if color <= 5:
                # Remove this frame
                for r,c in f['coords']:
                    result[r,c] = 0
            else:
                # Keep border, add pattern to interior
                # First ensure border is correct
                for r in range(bounds['r_min'], bounds['r_max']+1):
                    for c in range(bounds['c_min'], bounds['c_max']+1):
                        if r == bounds['r_min'] or r == bounds['r_max'] or c == bounds['c_min'] or c == bounds['c_max']:
                            if result[r,c] != color:
                                result[r,c] = color

                # Fill interior with pattern (simple placeholder)
                interior_filled = False

                # Try to detect if fill is needed (compare with input)
                # For simplicity, assume we always want to add some pattern
                # Use modulo pattern: fill if (r+c) % 2 == 0
                for r in range(bounds['r_min']+1, bounds['r_max']):
                    for c in range(bounds['c_min']+1, bounds['c_max']):
                        if result[r,c] == 0:  # Interior cell
                            if (r + c) % 2 == 0:  # Simple diagonal-ish fill
                                result[r,c] = color
                            elif (r + c) % 3 == 0:  # Additional cells
                                result[r,c] = color

    return result

