def generate_interior_pattern(height, width):
    """Generate diagonal bounce/gliller pattern for frame interior"""
    # Pattern seems to cycle every 4 rows in a specific way
    pattern = [[False]*width for _ in range(height)]

    if height == 2:
        return [[False]*width for _ in range(2)]

    for r in range(height):
        cycle = r % 4

