        # Row 1: 1 1 0 1 ... more filled
        # Row 2: 0 1 1 1 ...
        # Row 3: 1 1 0 0 ...

        # For a simple diagonal pattern, let's try:
        center = width // 2
        for c in range(width):
            dist = abs(c - center)
            if cycle == 0:
                pattern[r][c] = (dist > 0 and dist <= 1) or (c == center)
            elif cycle == 1:
                pattern[r][c] = dist <= 1
            elif cycle == 2:
                pattern[r][c] = dist >= 0  # mostly filled
            else:
                pattern[r][c] = dist < 2

